const state = { items: [], status: "idle", error: null };
function visibleItems(state, query) {
  return state.items.filter((item) => item.name.toLowerCase().includes(query.toLowerCase()));
}

function reducer(state, event) {
  switch (event.type) {
    case "load": return { ...state, status: "loading", error: null };
    case "success": return { ...state, status: "success", items: event.items };
    case "failure": return { ...state, status: "error", error: event.error };
    default: return state;
  }
}

type Result<T> = { ok: true; value: T } | { ok: false; error: string };
function unwrap<T>(result: Result<T>): T {
  if (!result.ok) throw new Error(result.error);
  return result.value;
}

function isUser(value: unknown): value is { id: string; name: string } {
  return typeof value === "object" && value !== null &&
    typeof (value as Record<string, unknown>).id === "string" &&
    typeof (value as Record<string, unknown>).name === "string";
}

